# Centralized role-based access control. Every authorisation check goes through here.
# Replace the default in-memory policy with a real store / library (Casbin, Oso, OPA).

from __future__ import annotations

from collections.abc import Awaitable, Callable, Mapping, Sequence
from typing import Protocol

from fastapi import HTTPException, Request

from .audit_log import audit_log

Role = str        # e.g. 'physician', 'admin', 'patient'
Permission = str  # e.g. 'patient:read', 'prescription:create', 'dsr:respond'


class PolicyStore(Protocol):
    def permissions_for(self, role: Role) -> Sequence[Permission]: ...
    async def roles_for(self, actor_id: str) -> Sequence[Role]: ...


_store: PolicyStore | None = None


def set_policy_store(store: PolicyStore) -> None:
    global _store
    _store = store


def _require_store() -> PolicyStore:
    if _store is None:
        raise RuntimeError('secure-by-design: PolicyStore not configured.')
    return _store


async def check(actor_id: str, permission: Permission) -> bool:
    """
    Check whether an actor has a permission. Returns bool.
    For control-flow gates, use `require_permission(...)` which raises.
    """
    store = _require_store()
    for role in await store.roles_for(actor_id):
        perms = store.permissions_for(role)
        if permission in perms or '*' in perms:
            return True
    return False


class PermissionDeniedError(HTTPException):
    code = 'PERMISSION_DENIED'

    def __init__(self, permission: Permission) -> None:
        super().__init__(status_code=403, detail=f'Permission denied: {permission}')


async def require_permission(actor_id: str, permission: Permission) -> None:
    """Raise if the actor does not have the permission. Audit-logs the check either way."""
    allowed = await check(actor_id, permission)
    await audit_log.security(
        'rbac.check',
        actor=actor_id,
        severity='INFO' if allowed else 'WARN',
        outcome='success' if allowed else 'denied',
        attrs={'permission': permission},
    )
    if not allowed:
        raise PermissionDeniedError(permission)


def requires(permission: Permission) -> Callable[[Request], Awaitable[None]]:
    """
    FastAPI dependency factory. Your auth layer sets request.state.user. Add it to a route
    with dependencies=[Depends(requires('patient:create'))].
    """

    async def dependency(request: Request) -> None:
        user = getattr(request.state, 'user', None)
        actor_id = user.get('id') if isinstance(user, Mapping) else getattr(user, 'id', None)
        if not actor_id:
            raise HTTPException(status_code=401, detail='unauthenticated')
        await require_permission(str(actor_id), permission)

    return dependency


class InMemoryPolicyStore:
    """Trivial default policy store for bootstrapping. REPLACE before production."""

    def __init__(
        self,
        roles_by_actor: Mapping[str, Sequence[Role]],
        permissions_by_role: Mapping[Role, Sequence[Permission]],
    ) -> None:
        self._roles_by_actor = roles_by_actor
        self._permissions_by_role = permissions_by_role

    def permissions_for(self, role: Role) -> Sequence[Permission]:
        return self._permissions_by_role.get(role, ())

    async def roles_for(self, actor_id: str) -> Sequence[Role]:
        return self._roles_by_actor.get(actor_id, ())
